// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import { test } from "node:test";

import {
  classifyWorktree,
  formatBytes,
  hasLanded,
  PROTECTED_BRANCHES,
} from "./worktree-reclaim.mjs";

const idle = {
  path: "C:/Repos/MindLeak-done",
  branch: "fix/something-that-shipped",
  bare: false,
  dirty: false,
  landed: true,
  owner: null,
  building: false,
};

test("reclaims a merged, clean, idle worktree", () => {
  const verdict = classifyWorktree(idle, { session: "session:v1:me" });
  assert.equal(verdict.reclaim, true);
  assert.equal(verdict.branch, "fix/something-that-shipped");
});

// Everything below is a refusal. A cleanup tool tested only on what it deletes
// has not been tested on what matters: no report can be un-deleted.

test("never takes the primary checkout", () => {
  const verdict = classifyWorktree({ ...idle, bare: true }, {});
  assert.equal(verdict.reclaim, false);
  assert.match(verdict.reason, /primary checkout/);
});

/**
 * Found on the first live run against 94 real worktrees. This tool's own
 * worktree was merged, clean and idle, so every other rule said yes — it would
 * have deleted `target/` out from under the running process and then tried to
 * remove the checkout it was executing in. A cleanup tool must not be its own
 * first casualty.
 */
test("never takes the worktree it is running in", () => {
  const verdict = classifyWorktree({ ...idle, current: true }, {});
  assert.equal(verdict.reclaim, false);
  assert.match(verdict.reason, /running here/);
});

test("never takes a protected branch, however merged it looks", () => {
  for (const branch of PROTECTED_BRANCHES) {
    const verdict = classifyWorktree({ ...idle, branch }, {});
    assert.equal(verdict.reclaim, false, `${branch} must be refused`);
    assert.match(verdict.reason, /protected/);
  }
});

test("never takes a tree with uncommitted or untracked changes", () => {
  // Untracked counts. A file nobody has staged yet exists nowhere else, which
  // makes it the most valuable thing in the tree rather than the least.
  const verdict = classifyWorktree({ ...idle, dirty: true }, {});
  assert.equal(verdict.reclaim, false);
  assert.match(verdict.reason, /uncommitted or untracked/);
});

test("never takes work that has not landed on origin/main", () => {
  const verdict = classifyWorktree({ ...idle, landed: false }, {});
  assert.equal(verdict.reclaim, false);
  assert.match(verdict.reason, /have not landed/);
});

test("never takes a worktree another session owns", () => {
  const verdict = classifyWorktree(
    { ...idle, owner: "session:v1:someone-else" },
    { session: "session:v1:me" },
  );
  assert.equal(verdict.reclaim, false);
  assert.match(verdict.reason, /owned by session/);
});

test("takes a worktree this session owns", () => {
  const verdict = classifyWorktree(
    { ...idle, owner: "session:v1:me" },
    { session: "session:v1:me" },
  );
  assert.equal(verdict.reclaim, true);
});

test("never takes a tree with a build running in it", () => {
  const verdict = classifyWorktree({ ...idle, building: true }, {});
  assert.equal(verdict.reclaim, false);
  assert.match(verdict.reason, /build is running/);
});

test("never takes a detached HEAD, because nothing names what it holds", () => {
  const verdict = classifyWorktree({ ...idle, branch: null }, {});
  assert.equal(verdict.reclaim, false);
  assert.match(verdict.reason, /detached/);
});

/**
 * The regression this rule exists for. A squash or rebase merge lands every
 * line under a NEW commit id, so `git merge-base --is-ancestor` answers "no"
 * for work that is fully merged. An agent here used ancestry, concluded 245
 * merged lines were lost, and queued a PR to restore code already on main.
 *
 * `git cherry` marks an upstream-equivalent patch `-` and a genuinely absent
 * one `+`, which is the question actually being asked.
 */
test("treats a squash-merged branch as landed, not as lost work", () => {
  assert.equal(
    hasLanded("- 1a2b3c squashed away\n- 4d5e6f also landed\n"),
    true,
  );
});

test("treats a branch with any unlanded commit as not landed", () => {
  assert.equal(hasLanded("- 1a2b3c landed\n+ 9f8e7d never landed\n"), false);
});

test("treats a branch with no commits as landed", () => {
  assert.equal(hasLanded("\n  \n"), true);
});

test("reports sizes in a unit a human can decide on", () => {
  assert.equal(formatBytes(0), "0.00 GiB");
  assert.equal(formatBytes(1024 ** 3), "1.00 GiB");
});
